# API Gateway routing table — illustrates path-to-service mapping
ROUTES = {
    '/api/users':    {'host': 'localhost', 'port': 8001, 'strip_prefix': '/api'},
    '/api/orders':   {'host': 'localhost', 'port': 8002, 'strip_prefix': '/api'},
    '/api/products': {'host': 'localhost', 'port': 8003, 'strip_prefix': '/api'},
}

def resolve_route(path):
    for prefix, target in ROUTES.items():
        if path.startswith(prefix):
            upstream_path = path[len(target['strip_prefix']):]
            return f"http://{target['host']}:{target['port']}{upstream_path}"
    return None

test_paths = ['/api/users/42', '/api/orders/7', '/api/products', '/api/unknown']
for p in test_paths:
    dest = resolve_route(p)
    if dest:
        print(f'GET {p}  ->  {dest}')
    else:
        print(f'GET {p}  ->  404 No route matched')
